1: import React, { useState, useEffect } from 'react';
2: import { useNavigate } from 'react-router-dom';
3: import TopNav from '../components/TopNav';
4: 
5: const DEFAULT_PET_IMAGES = {
6:   Dog: 'https://images.unsplash.com/photo-1543466835-00a7907e9de1?w=500&auto=format&fit=crop',
7:   Cat: 'https://images.unsplash.com/photo-1514888286974-6c03e2ca1dba?w=500&auto=format&fit=crop',
8:   Bird: 'https://images.unsplash.com/photo-1552728089-57bdde30beb3?w=500&auto=format&fit=crop',
9:   Rabbit: 'https://images.unsplash.com/photo-1585110396000-c9ffd4e4b308?w=500&auto=format&fit=crop',
10:   Other: 'https://images.unsplash.com/photo-1425082661705-1834bfd09dca?w=500&auto=format&fit=crop'
11: };
12: 
13: const INITIAL_FORM_STATE = {
14:   name: '',
15:   species: 'Dog',
16:   breed: '',
17:   gender: 'Male',
18:   age: 1,
19:   ageUnit: 'Years',
20:   weight: 5,
21:   weightUnit: 'kg',
22:   color: '',
23:   image: '',
24:   description: '',
25:   vaccinated: true,
26:   vaccinationDate: new Date().toISOString().split('T')[0],
27:   healthStatus: 'Healthy',
28:   status: 'Available'
29: };
30: 
31: const MyPets = () => {
32:   const [pets, setPets] = useState([]);
33:   const [loading, setLoading] = useState(true);
34:   const [user, setUser] = useState(null);
35:   const [token, setToken] = useState('');
36:   const [searchQuery, setSearchQuery] = useState('');
37:   const [selectedSpecies, setSelectedSpecies] = useState('All');
38: 
39:   // Modals state
40:   const [isAddModalOpen, setIsAddModalOpen] = useState(false);
41:   const [isEditModalOpen, setIsEditModalOpen] = useState(false);
42:   const [isViewModalOpen, setIsViewModalOpen] = useState(false);
43:   const [selectedPet, setSelectedPet] = useState(null);
44: 
45:   // Form & Upload state
46:   const [formData, setFormData] = useState(INITIAL_FORM_STATE);
47:   const [uploadingImage, setUploadingImage] = useState(false);
48:   const [formSubmitting, setFormSubmitting] = useState(false);
49:   const [toastMessage, setToastMessage] = useState(null);
50: 
51:   const navigate = useNavigate();
52: 
53:   useEffect(() => {
54:     const storedUser = localStorage.getItem('currentUser');
55:     const storedToken = localStorage.getItem('userToken');
56:     if (!storedUser) {
57:       navigate('/login');
58:       return;
59:     }
60:     const parsedUser = JSON.parse(storedUser);
61:     setUser(parsedUser);
62:     setToken(storedToken || '');
63:     fetchPets(parsedUser);
64:   }, [navigate]);
65: 
66:   const showToast = (msg, type = 'success') => {
67:     setToastMessage({ text: msg, type });
68:     setTimeout(() => setToastMessage(null), 3500);
69:   };
70: 
71:   const fetchPets = async (currentUser) => {
72:     setLoading(true);
73:     try {
74:       const ownerId = currentUser._id || currentUser.id;
75:       const res = await fetch(`${import.meta.env.VITE_API_URL}/api/pets?ownerId=${ownerId}`);
76:       if (res.ok) {
77:         const data = await res.json();
78:         setPets(data.data || []);
79:       } else {
80:         console.error('Failed to fetch pets');
81:       }
82:     } catch (err) {
83:       console.error('Error fetching pets:', err);
84:     } finally {
85:       setLoading(false);
86:     }
87:   };
88: 
89:   // ImageKit File Upload Handler
90:   const handleImageUpload = (e) => {
91:     const file = e.target.files[0];
92:     if (!file) return;
93: 
94:     setUploadingImage(true);
95:     const reader = new FileReader();
96:     reader.readAsDataURL(file);
97:     reader.onload = async () => {
98:       try {
99:         const res = await fetch(`${import.meta.env.VITE_API_URL}/api/imagekit/upload`, {
100:           method: 'POST',
101:           headers: { 'Content-Type': 'application/json' },
102:           body: JSON.stringify({
103:             file: reader.result,
104:             fileName: `pet_${Date.now()}_${file.name}`,
105:             folder: '/pets'
106:           })
107:         });
108:         const data = await res.json();
109:         if (res.ok && data.success && data.url) {
110:           setFormData((prev) => ({ ...prev, image: data.url }));
111:           showToast('Image uploaded successfully to ImageKit!');
112:         } else {
113:           showToast(data.message || 'Image upload failed. Ensure your ImageKit keys in Render are valid.', 'error');
114:         }
115:       } catch (err) {
116:         showToast('Image upload error: ' + err.message, 'error');
117:       } finally {
118:         setUploadingImage(false);
119:       }
120:     };
121:   };
122: 
123:   // Open Add Modal
124:   const handleOpenAddModal = () => {
125:     setFormData(INITIAL_FORM_STATE);
126:     setIsAddModalOpen(true);
127:   };
128: 
129:   // Open Edit Modal
130:   const handleOpenEditModal = (pet) => {
131:     setSelectedPet(pet);
132:     setFormData({
133:       name: pet.name || '',
134:       species: pet.species || pet.type || 'Dog',
135:       breed: pet.breed || '',
136:       gender: pet.gender || 'Male',
137:       age: pet.age !== undefined ? pet.age : 1,
138:       ageUnit: pet.ageUnit || 'Years',
139:       weight: pet.weight !== undefined ? pet.weight : 5,
140:       weightUnit: pet.weightUnit || 'kg',
141:       color: pet.color || '',
142:       image: pet.image || '',
143:       description: pet.description || '',
144:       vaccinated: pet.vaccinated !== undefined ? pet.vaccinated : true,
145:       vaccinationDate: pet.vaccinationDate ? new Date(pet.vaccinationDate).toISOString().split('T')[0] : new Date().toISOString().split('T')[0],
146:       healthStatus: pet.healthStatus || 'Healthy',
147:       status: pet.status || 'Available'
148:     });
149:     setIsEditModalOpen(true);
150:   };
151: 
152:   // Submit Add Pet
153:   const handleAddPetSubmit = async (e) => {
154:     e.preventDefault();
155:     setFormSubmitting(true);
156:     try {
157:       const ownerId = user._id || user.id;
158:       const payload = {
159:         ...formData,
160:         type: formData.species, // explicitly set type for the Render backend
161:         ownerId,
162:         ownerName: user.name || '',
163:         ownerEmail: user.email || '',
164:         ownerPhone: user.phone || ''
165:       };
166: 
167:       const res = await fetch(`${import.meta.env.VITE_API_URL}/api/pets`, {
168:         method: 'POST',
169:         headers: {
170:           'Content-Type': 'application/json',
171:           Authorization: `Bearer ${token}`
172:         },
173:         body: JSON.stringify(payload)
174:       });
175: 
176:       const data = await res.json();
177:       if (res.ok && data.success) {
178:         showToast('Pet registered successfully!');
179:         setIsAddModalOpen(false);
180:         setFormData(INITIAL_FORM_STATE);
181:         fetchPets(user);
182:       } else {
183:         showToast(data.message || 'Failed to add pet', 'error');
184:       }
185:     } catch (err) {
186:       showToast('Error registering pet: ' + err.message, 'error');
187:     } finally {
188:       setFormSubmitting(false);
189:     }
190:   };
191: 
192:   // Submit Edit Pet
193:   const handleEditPetSubmit = async (e) => {
194:     e.preventDefault();
195:     if (!selectedPet) return;
196: 
197:     setFormSubmitting(true);
198:     try {
199:       const petId = selectedPet._id || selectedPet.id;
200:       
201:       const payload = {
202:         ...formData,
203:         type: formData.species
204:       };
205: 
206:       const res = await fetch(`${import.meta.env.VITE_API_URL}/api/pets/${petId}`, {
207:         method: 'PUT',
208:         headers: {
209:           'Content-Type': 'application/json',
210:           Authorization: `Bearer ${token}`
211:         },
212:         body: JSON.stringify(payload)
213:       });
214: 
215:       const data = await res.json();
216:       if (res.ok && data.success) {
217:         showToast('Pet details updated successfully!');
218:         setIsEditModalOpen(false);
219:         setSelectedPet(null);
220:         fetchPets(user);
221:       } else {
222:         showToast(data.message || 'Failed to update pet', 'error');
223:       }
224:     } catch (err) {
225:       showToast('Error updating pet: ' + err.message, 'error');
226:     } finally {
227:       setFormSubmitting(false);
228:     }
229:   };
230: 
231:   // Delete Pet
232:   const handleDeletePet = async (pet) => {
233:     const petId = pet._id || pet.id;
234:     if (!window.confirm(`Are you sure you want to delete ${pet.name}?`)) return;
235: 
236:     try {
237:       const res = await fetch(`${import.meta.env.VITE_API_URL}/api/pets/${petId}`, {
238:         method: 'DELETE',
239:         headers: {
240:           Authorization: `Bearer ${token}`
241:         }
242:       });
243:       const data = await res.json();
244:       if (res.ok && data.success) {
245:         showToast(`${pet.name} has been removed.`);
246:         fetchPets(user);
247:       } else {
248:         showToast(data.message || 'Failed to delete pet', 'error');
249:       }
250:     } catch (err) {
251:       showToast('Error deleting pet: ' + err.message, 'error');
252:     }
253:   };
254: 
255:   // Set Favorite Pet (Updates TopNav avatar)
256:   const handleSetFavorite = (pet) => {
257:     const petSpecies = pet.species || pet.type;
258:     const petImg = pet.image || DEFAULT_PET_IMAGES[petSpecies] || DEFAULT_PET_IMAGES.Other;
259:     localStorage.setItem('favoritePetImage', petImg);
260:     window.dispatchEvent(new Event('favoritePetChanged'));
261:     showToast(`${pet.name} set as favorite pet profile photo!`);
262:   };
263: 
264:   // Filtered pets list
265:   const filteredPets = pets.filter((pet) => {
266:     const petSpecies = pet.species || pet.type;
267:     const matchesSpecies = selectedSpecies === 'All' || petSpecies?.toLowerCase() === selectedSpecies.toLowerCase();
268:     const matchesSearch = pet.name?.toLowerCase().includes(searchQuery.toLowerCase()) ||
269:                           pet.breed?.toLowerCase().includes(searchQuery.toLowerCase());
270:     return matchesSpecies && matchesSearch;
271:   });
272: 
273:   return (
274:     <div className="p-4 md:p-8 max-w-7xl mx-auto space-y-6">
275:       <TopNav
276:         title="My Pet Companions"
277:         subtitle="View, add, and manage your pets' health records, vaccination schedules, and profile details."
278:       />
279: 
280:       {/* Toast Notification */}
281:       {toastMessage && (
282:         <div
283:           className={`fixed top-4 right-4 z-50 px-4 py-3 rounded-xl shadow-lg border text-sm font-semibold flex items-center gap-2 animate-bounce ${
284:             toastMessage.type === 'error'
285:               ? 'bg-red-900/90 text-red-100 border-red-500'
286:               : 'bg-emerald-900/90 text-emerald-100 border-emerald-500'
287:           }`}
288:         >
289:           <span className="material-symbols-outlined text-[20px]">
290:             {toastMessage.type === 'error' ? 'error' : 'check_circle'}
291:           </span>
292:           {toastMessage.text}
293:         </div>
294:       )}
295: 
296:       {/* Control Bar: Filters & Add Button */}
297:       <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-surface-container-low p-4 rounded-2xl border border-outline-variant/30 shadow-sm">
298:         {/* Species Filter & Search */}
299:         <div className="flex flex-wrap items-center gap-2 w-full md:w-auto">
300:           {['All', 'Dog', 'Cat', 'Bird', 'Rabbit', 'Other'].map((spec) => (
301:             <button
302:               key={spec}
303:               onClick={() => setSelectedSpecies(spec)}
304:               className={`px-3 py-1.5 rounded-xl text-xs font-bold transition-all ${
305:                 selectedSpecies === spec
306:                   ? 'bg-primary text-white shadow-sm'
307:                   : 'bg-surface-container text-on-surface-variant hover:bg-surface-container-high'
308:               }`}
309:             >
310:               {spec}
311:             </button>
312:           ))}
313:         </div>
314: 
315:         <div className="flex items-center gap-3 w-full md:w-auto justify-between md:justify-end">
316:           {/* Search Input */}
317:           <div className="relative w-full md:w-64">
318:             <span className="material-symbols-outlined absolute left-3 top-1/2 -translate-y-1/2 text-outline-variant text-[18px]">
319:               search
320:             </span>
321:             <input
322:               type="text"
323:               placeholder="Search by name or breed..."
324:               value={searchQuery}
325:               onChange={(e) => setSearchQuery(e.target.value)}
326:               className="w-full pl-9 pr-3 py-2 bg-surface-container border border-outline-variant/40 rounded-xl text-xs focus:outline-none focus:border-primary text-on-surface"
327:             />
328:           </div>
329: 
330:           {/* Add New Pet Button */}
331:           <button
332:             onClick={handleOpenAddModal}
333:             className="bg-primary text-on-primary font-bold px-4 py-2 rounded-xl text-xs shadow-md hover:bg-surface-tint transition-all flex items-center gap-1.5 shrink-0"
334:           >
335:             <span className="material-symbols-outlined text-[18px]">add</span> Add New Pet
336:           </button>
337:         </div>
338:       </div>
339: 
340:       {/* Pets Grid */}
341:       {loading ? (
342:         <div className="flex flex-col items-center justify-center py-20 space-y-3">
343:           <span className="material-symbols-outlined text-4xl text-primary animate-spin">sync</span>
344:           <p className="text-xs font-bold text-on-surface-variant">Loading pet profiles...</p>
345:         </div>
346:       ) : filteredPets.length === 0 ? (
347:         <div className="text-center py-16 bg-surface-container-lowest border border-dashed border-outline-variant rounded-2xl p-8 space-y-4">
348:           <span className="material-symbols-outlined text-5xl text-outline-variant">pets</span>
349:           <div>
350:             <h3 className="text-lg font-bold text-on-surface">No Pet Companions Found</h3>
351:             <p className="text-xs text-on-surface-variant mt-1">
352:               {searchQuery || selectedSpecies !== 'All'
353:                 ? 'No pets match your search criteria or species filter.'
354:                 : 'You have not registered any pets yet. Click below to add your first pet!'}
355:             </p>
356:           </div>
357:           <button
358:             onClick={handleOpenAddModal}
359:             className="bg-primary text-white text-xs font-bold px-5 py-2.5 rounded-xl shadow-md hover:bg-surface-tint transition-all inline-flex items-center gap-2"
360:           >
361:             <span className="material-symbols-outlined text-[18px]">add</span> Register First Pet
362:           </button>
363:         </div>
364:       ) : (
365:         <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
366:           {filteredPets.map((pet) => {
367:             const petSpecies = pet.species || pet.type;
368:             const petImg = pet.image || DEFAULT_PET_IMAGES[petSpecies] || DEFAULT_PET_IMAGES.Other;
369:             return (
370:               <div
371:                 key={pet._id || pet.id}
372:                 className="bg-surface-container-lowest rounded-2xl border border-outline-variant/30 overflow-hidden shadow-sm hover:shadow-md transition-all flex flex-col justify-between"
373:               >
374:                 {/* Pet Image & Badges */}
375:                 <div className="relative h-48 w-full bg-surface-container overflow-hidden">
376:                   <img
377:                     src={petImg}
378:                     alt={pet.name}
379:                     className="w-full h-full object-cover transition-transform duration-300 hover:scale-105"
380:                     onError={(e) => {
381:                       e.target.src = DEFAULT_PET_IMAGES.Other;
382:                     }}
383:                   />
384:                   <div className="absolute top-3 left-3 flex flex-wrap gap-1.5">
385:                     <span className="bg-black/60 backdrop-blur-md text-white text-[10px] font-extrabold px-2.5 py-1 rounded-full uppercase tracking-wider">
386:                       {petSpecies}
387:                     </span>
388:                     <span
389:                       className={`text-[10px] font-extrabold px-2.5 py-1 rounded-full uppercase tracking-wider backdrop-blur-md ${
390:                         pet.healthStatus === 'Healthy'
391:                           ? 'bg-emerald-500/90 text-white'
392:                           : pet.healthStatus === 'Sick'
393:                           ? 'bg-red-500/90 text-white'
394:                           : 'bg-amber-500/90 text-white'
395:                       }`}
396:                     >
397:                       {pet.healthStatus || 'Healthy'}
398:                     </span>
399:                   </div>
400: 
401:                   <button
402:                     onClick={() => handleSetFavorite(pet)}
403:                     title="Set as favorite pet for top navbar avatar"
404:                     className="absolute top-3 right-3 bg-white/80 backdrop-blur-md hover:bg-white text-rose-500 p-1.5 rounded-full shadow-md transition-all"
405:                   >
406:                     <span className="material-symbols-outlined text-[18px] filled-icon">favorite</span>
407:                   </button>
408:                 </div>
409: 
410:                 {/* Pet Details */}
411:                 <div className="p-5 space-y-4 flex-1">
412:                   <div>
413:                     <div className="flex justify-between items-start">
414:                       <h3 className="text-xl font-black text-on-surface">{pet.name}</h3>
415:                       <span className="text-xs font-bold text-primary bg-primary/10 px-2.5 py-0.5 rounded-full">
416:                         {pet.gender}
417:                       </span>
418:                     </div>
419:                     <p className="text-xs font-bold text-on-surface-variant mt-0.5">
420:                       {pet.breed || 'Mixed Breed'} {pet.color ? `• ${pet.color}` : ''}
421:                     </p>
422:                   </div>
423: 
424:                   <div className="grid grid-cols-2 gap-2 text-xs bg-surface-container-low p-3 rounded-xl border border-outline-variant/20">
425:                     <div>
426:                       <span className="text-[10px] text-on-surface-variant block uppercase font-bold">Age</span>
427:                       <span className="font-bold text-on-surface">
428:                         {pet.age} {pet.ageUnit || 'Years'}
429:                       </span>
430:                     </div>
431:                     <div>
432:                       <span className="text-[10px] text-on-surface-variant block uppercase font-bold">Weight</span>
433:                       <span className="font-bold text-on-surface">
434:                         {pet.weight} {pet.weightUnit || 'kg'}
435:                       </span>
436:                     </div>
437:                   </div>
438: 
439:                   <div className="flex items-center justify-between text-xs pt-1">
440:                     <div className="flex items-center gap-1.5">
441:                       <span
442:                         className={`w-2 h-2 rounded-full ${
443:                           pet.vaccinated ? 'bg-emerald-500' : 'bg-red-500'
444:                         }`}
445:                       ></span>
446:                       <span className="font-bold text-on-surface">
447:                         {pet.vaccinated ? 'Vaccinated' : 'Not Vaccinated'}
448:                       </span>
449:                     </div>
450:                     <span className="text-[11px] text-on-surface-variant">
451:                       Status: <strong className="text-on-surface">{pet.status || 'Available'}</strong>
452:                     </span>
453:                   </div>
454: 
455:                   {pet.description && (
456:                     <p className="text-xs text-on-surface-variant/90 line-clamp-2 italic">
457:                       "{pet.description}"
458:                     </p>
459:                   )}
460:                 </div>
461: 
462:                 {/* Card Actions */}
463:                 <div className="p-4 border-t border-outline-variant/20 bg-surface-container-lowest flex items-center justify-between gap-2">
464:                   <button
465:                     onClick={() => {
466:                       setSelectedPet(pet);
467:                       setIsViewModalOpen(true);
468:                     }}
469:                     className="text-xs font-bold text-primary hover:underline flex items-center gap-1"
470:                   >
471:                     <span className="material-symbols-outlined text-[16px]">visibility</span> View Details
472:                   </button>
473: 
474:                   <div className="flex items-center gap-1">
475:                     <button
476:                       onClick={() => handleOpenEditModal(pet)}
477:                       className="p-2 text-on-surface-variant hover:text-primary hover:bg-surface-container rounded-xl transition-all"
478:                       title="Edit Pet Profile"
479:                     >
480:                       <span className="material-symbols-outlined text-[18px]">edit</span>
481:                     </button>
482:                     <button
483:                       onClick={() => handleDeletePet(pet)}
484:                       className="p-2 text-on-surface-variant hover:text-red-500 hover:bg-red-50 rounded-xl transition-all"
485:                       title="Delete Pet"
486:                     >
487:                       <span className="material-symbols-outlined text-[18px]">delete</span>
488:                     </button>
489:                   </div>
490:                 </div>
491:               </div>
492:             );
493:           })}
494:         </div>
495:       )}
496: 
497:       {/* ========================================================================= */}
498:       {/* ADD / EDIT PET MODAL FORM */}
499:       {/* ========================================================================= */}
500:       {(isAddModalOpen || isEditModalOpen) && (
501:         <div className="fixed inset-0 z-50 bg-black/60 backdrop-blur-sm flex items-center justify-center p-4 overflow-y-auto animate-fade-in">
502:           <div className="bg-surface-container-lowest rounded-2xl max-w-2xl w-full border border-outline-variant/40 shadow-2xl overflow-hidden my-8">
503:             {/* Modal Header */}
504:             <div className="p-5 border-b border-outline-variant/30 flex justify-between items-center bg-surface-container-low">
505:               <div className="flex items-center gap-2">
506:                 <span className="material-symbols-outlined text-primary text-2xl">
507:                   {isEditModalOpen ? 'edit_note' : 'add_circle'}
508:                 </span>
509:                 <h2 className="text-xl font-black text-on-surface">
510:                   {isEditModalOpen ? `Edit ${selectedPet?.name}'s Profile` : 'Add New Pet Companion'}
511:                 </h2>
512:               </div>
513:               <button
514:                 onClick={() => {
515:                   setIsAddModalOpen(false);
516:                   setIsEditModalOpen(false);
517:                 }}
518:                 className="text-on-surface-variant hover:text-on-surface p-1 rounded-lg"
519:               >
520:                 <span className="material-symbols-outlined text-2xl">close</span>
521:               </button>
522:             </div>
523: 
524:             {/* Modal Form */}
525:             <form onSubmit={isEditModalOpen ? handleEditPetSubmit : handleAddPetSubmit} className="p-6 space-y-4">
526:               {/* Photo Upload Section */}
527:               <div className="space-y-2">
528:                 <label className="block text-xs font-bold uppercase text-on-surface-variant">
529:                   Pet Profile Photo
530:                 </label>
531:                 <div className="flex items-center gap-4">
532:                   <div className="w-20 h-20 rounded-2xl bg-surface-container overflow-hidden border border-outline-variant/50 relative shrink-0">
533:                     <img
534:                       src={
535:                         formData.image ||
536:                         DEFAULT_PET_IMAGES[formData.species] ||
537:                         DEFAULT_PET_IMAGES.Other
538:                       }
539:                       alt="Preview"
540:                       className="w-full h-full object-cover"
541:                     />
